def is_valid_regex(regex: str) -> bool:
    stack = []
    escape_next = False
    for char in regex:
        if escape_next:
            escape_next = False
            continue
        if char == '\\':
            escape_next = True
            continue
        elif char == '(':
            stack.append(char)
            continue
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
        elif char == '[':
            stack.append(char)
            continue
        elif char == ']':
            if not stack or stack[-1] != '[':
                return False
            stack.pop()

    return not stack
```

