def is_trivial_dependency(V, functional_dependencies):
    for dependency in functional_dependencies:
        left_vars = dependency[:-1]
        right_var = dependency[-1]
        if check_trivial_dependency(V, left_vars, right_var):
            return True

    return False

def check_trivial_dependency(V, left_vars, right_var):
    for i in range(2 ** len(V)):
        binary_str = format(i, 'b').zfill(len(V))
        values = dict(zip(V, binary_str))
        if check_dependency(left_vars, right_var, values):
            return True

    return False

def check_dependency(left_vars, right_var, values):
    for var in left_vars:
        if values[var] != values[right_var]:
            return False

    return True
