```python
import logging

def step_iter(seq, step=1):
    logger = logging.getLogger(__name__)

    if not isinstance(seq, list):
        logger.error('Input sequence is not list-like')
        raise Exception('Input sequence is not list-like')

    if step > 0:
        for i in range(0, len(seq), step):
            yield seq[i]
    elif step < 0:
        for i in range(len(seq)-1, -1, step):
            yield seq[i]
    else:
        logger.warning('Step size is 0, no elements will be yielded')
