import time

def rate_limit(max_calls, time_window):
    calls_count = {}

    def decorator(fn):
        def wrapper(*args, **kwargs):
            current_time = time.time()
            if fn not in calls_count:
                calls_count[fn] = {'time': current_time, 'count': 1}
            else:
                if current_time - calls_count[fn]['time'] < time_window:
                    if calls_count[fn]['count'] + 1 > max_calls:
                        raise Exception("Rate limit exceeded")
                    calls_count[fn]['count'] += 1
                else:
                    calls_count[fn]['time'] = current_time
                    calls_count[fn]['count'] = 1
            return fn(*args, **kwargs)
        return wrapper

    return decorator
```

