from typing import TypeVar, Generic
T = TypeVar('T')

class Stack(Generic[T]):
    def __init__(self):
        self.elements = []

    def push(self, element: T) -> None:
        self.elements.append(element)

    def pop(self) -> T:
        if self.isEmpty():
            raise Exception("Stack is empty")
        return self.elements.pop()

    def top(self) -> T:
        if self.isEmpty():
            raise Exception("Stack is empty")
        return self.elements[-1]

