```python
import numpy as np

def gaussian_log_pdf(x, mean, variance):
    """
    Calculates the log probability of x under a Gaussian distribution with
    the given mean and variance.

    Args:
        x: The value to calculate the probability of.
        mean: The mean of the Gaussian distribution.
        variance: The variance of the Gaussian distribution.

    Returns:
        The log probability of x under a Gaussian distribution with the given
        mean and variance.
    """
    def f1(x, mean, variance):
        return (1 / (variance * np.sqrt(2 * np.pi))) * np.exp(-((x - mean) ** 2) / (2 * variance ** 2))
    def f2(x):
        return np.log(x)
    def f3(x, mean, variance):
        return (x - mean) / variance
    def f4(variance):
        return np.log(variance)
    return f2(f1(x, mean, variance)) + f3(x, mean, variance) + f4(variance)
```

