def is_prime(n):
    if n == 2:
        return True
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

def get_prime_factors(n):
    if n < 1:
        raise ValueError("n must be a positive integer")
    prime_factors = []
    if is_prime(n):
        return [n]
    for i in range(2, int(n ** 0.5) + 1):
